-- Reference schema; Hibernate generates actual tables from annotations.
CREATE TABLE categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500));
CREATE TABLE products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(150) NOT NULL,price DECIMAL(12,2) NOT NULL,stock_quantity INTEGER NOT NULL,category_id BIGINT NOT NULL REFERENCES categories(id),deleted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,role VARCHAR(20) NOT NULL);
CREATE TABLE orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_date TIMESTAMP NOT NULL,total_amount DECIMAL(12,2) NOT NULL,user_id BIGINT NOT NULL REFERENCES users(id));
CREATE TABLE order_details(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quantity INTEGER NOT NULL,unit_price DECIMAL(12,2) NOT NULL,order_id BIGINT NOT NULL REFERENCES orders(id),product_id BIGINT NOT NULL REFERENCES products(id));